output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file aisles, identified by horizontal free width of at most one cell.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_between_opposing_shelves",
    "text": "Shopping carts are prohibited in narrow product aisles where shelves face the shopper from both east and west.",
    "abstraction": {
      "state_properties": {
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "between_opposing_shelves"
        ]
      }
    }
  },
  {
    "id": "no_pushing_cart_into_handcarry_aisle",
    "text": "A shopper must not push a cart into a hand-carry aisle formed by a single-file passage between opposing shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handcarry_aisle": {
          "and": [
            "single_file_aisle",
            "between_opposing_shelves"
          ]
        }
      },
      "events": {
        "push_cart_into_handcarry_aisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "handcarry_aisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_into_handcarry_aisle"
    }
  },
  {
    "id": "park_cart_only_at_handcarry_mouth",
    "text": "If a shopper sets down a cart, it should only be at the wide mouth of a hand-carry aisle.",
    "abstraction": {
      "state_properties": {
        "wide_cross_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "handcarry_aisle_mouth": {
          "and": [
            "wide_cross_aisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "handcarry_aisle_mouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking_at_mouth",
    "text": "After parking a cart at the mouth of a hand-carry aisle, the shopper is obliged to retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "wide_cross_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "handcarry_aisle_mouth": {
          "and": [
            "wide_cross_aisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "park_cart_at_mouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "handcarry_aisle_mouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart_at_mouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "handcarry_aisle_mouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart_at_mouth",
      "discharge": "retrieve_cart_at_mouth"
    }
  },
  {
    "id": "return_to_cart_after_handcarry_item",
    "text": "After taking an item on foot from a hand-carry aisle, the shopper must return to and pick up the parked cart.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handcarry_aisle": {
          "and": [
            "single_file_aisle",
            "between_opposing_shelves"
          ]
        },
        "wide_cross_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "handcarry_aisle_mouth": {
          "and": [
            "wide_cross_aisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "take_handcarry_item_on_foot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "handcarry_aisle"
            ]
          },
          "post": null
        },
        "retrieve_cart_at_mouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "handcarry_aisle_mouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_handcarry_item_on_foot",
      "discharge": "retrieve_cart_at_mouth"
    }
  },
  {
    "id": "no_cartless_wandering_outside_handcarry_zone",
    "text": "Walking without a cart is prohibited except within a hand-carry aisle or at its immediately associated cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handcarry_aisle": {
          "and": [
            "single_file_aisle",
            "between_opposing_shelves"
          ]
        },
        "wide_cross_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        },
        "handcarry_aisle_mouth": {
          "and": [
            "wide_cross_aisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        },
        "cartless_service_zone": {
          "or": [
            "handcarry_aisle",
            "handcarry_aisle_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartless_service_zone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_accessible_shelf_service",
    "text": "Shelf interactions from cart-accessible aisles should be performed with the cart, while only single-file hand-carry aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "between_opposing_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "handcarry_aisle": {
          "and": [
            "single_file_aisle",
            "between_opposing_shelves"
          ]
        },
        "cart_accessible_shelf_position": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "not": "handcarry_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cart_accessible_shelf_position",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
